'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),c=require('./native-fixtures-20261003.cjs').environment().ctx,results=[];
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
const G='甲乙丙丁戊己庚辛壬癸',B='寅卯辰巳午未申酉戌亥子丑';
function facts(g,m,stems=['庚','壬','丙'],branches=['申','辰','寅','子'],hiddenStems=['庚','壬','甲','癸']){return {dm:g,stems:['year','month','day','hour'].map((pillar,i)=>({pillar,label:pillar,stem:i===2?g:stems[i<2?i:2],constraints:[]})),hidden:['year','month','day','hour'].map((pillar,i)=>({pillar,label:pillar,branch:i===1?m:branches[i],stem:hiddenStems[i]}))};}
test('120日干×節令月入口皆有具體校錄原文、逐條實算十干透藏與原文條件',()=>{assert.equal(Object.keys(c.JYQiongtongData.entries).length,120);let total=0;for(const g of G)for(const m of B){const r=c.JYBaziQiongtong.evaluate(facts(g,m));assert.equal(r.stems.length,10);assert(r.sourceParagraphs.length);assert.equal(r.dayStem,g);assert.equal(r.monthBranch,m);for(const check of r.checks){assert(check.clause);assert(check.conditions.every(x=>typeof x.satisfied==='boolean'));total++;}}assert(total>500);});
test('三月甲木庚壬兩透原文字面條件：兩者透、藏而未透、缺一分别實算',()=>{const r=c.JYBaziQiongtong.evaluate(facts('甲','辰',['庚','壬','丙'])),x=r.checks.find(r=>r.clause.includes('庚壬兩透'));assert(x);assert.equal(x.observablePremises,'present');const n=c.JYBaziQiongtong.evaluate(facts('甲','辰',['庚','丁','丙'])),y=n.checks.find(r=>r.clause.includes('庚壬兩透'));assert.equal(y.observablePremises,'not-all-present');assert(!y.conditions.find(r=>r.id==='exposed-庚壬').satisfied);});
test('正月甲木癸藏丙透與無丙癸正反條件、隱干和日主不冒充額外透干',()=>{const r=c.JYBaziQiongtong.evaluate(facts('甲','寅',['丙','戊','庚'],['申','寅','寅','子'],['庚','甲','甲','癸']));const x=r.checks.find(r=>r.clause.includes('癸藏丙透'));assert(x&&x.conditions.find(r=>r.id==='hidden-癸').satisfied&&x.conditions.find(r=>r.id==='exposed-丙').satisfied);const y=r.checks.find(r=>r.clause.includes('如無丙癸'));assert(y&&!y.conditions[0].satisfied);assert.equal(r.stems.find(x=>x.stem==='甲').exposed.length,0);});
test('支局只列真實三支骨架，古文清濁強弱成化和風水前提保留未知',()=>{const f=facts('甲','寅',['庚','戊','丙'],['巳','寅','酉','丑']),r=c.JYBaziQiongtong.evaluate(f);assert(r.checks.some(r=>r.conditions.some(x=>x.id==='bureau-structure-金'&&x.satisfied)));for(const x of r.checks.filter(x=>x.qualitativeRequirements.length))assert.equal(x.fullRuleStatus,'requires-contextual-judgment');});
test('乙丑原数字本重複十一月標題，冬月通則与校勘待核都明列，不偽造十二月專段',()=>{const r=c.JYBaziQiongtong.evaluate(facts('乙','丑'));assert.equal(r.sourceScope,'combined-season');assert(r.policy.sourceAudit.includes('重複十一月'));assert(r.sourceParagraphs.every(p=>p.months.includes(12)));});
test('既有八字原局實算、JSON與提示詞同步載入源句及條件，不改格局及旺衰計算',()=>{const b=c.computeBazi(1983,8,25,14,55,'male',{timezoneOffset:8,trueSolarTime:false,referenceDate:'2026-10-03T04:00:00Z'});c.enhanceBazi(b);assert.equal(b.seasonalAssessment.classicalClauses.dayStem,'乙');assert.equal(b.seasonalAssessment.classicalClauses.monthBranch,'申');const a=c.JYNativeAnalysis.analyze('bazi',b),p=c.JYNativeAnalysis.prompt('bazi',b,'深入分析',{supplement:true});assert(a.seasonal.classicalClauses);assert(p.includes('sourceParagraphs')&&p.includes('QT-乙7-'));assert(!/NaN|undefined/.test(p));});
fs.writeFileSync(path.join(__dirname,'../docs/bazi-qiongtong-validation-20261003.json'),JSON.stringify({testedAt:new Date().toISOString(),passed:results.length,failed:0,sourceEntries:120,grammar:'Explicit literal stems/branches and exact day/hour predicates. Qualitative effective transformation, balance and luck conditions retained for full-context judgment; this is not a claim that all ancient sentences have a unique Boolean algorithm.',results},null,2));
